import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.8','Arbeitssicherheit, Ziff.')
F="Der Eisenbahnbetrieb birgt besondere Gefahren in sich und verlangt von allen Mitarbeitenden eine erhöhte Aufmerksamkeit. Der Gleisbereich darf nur betreten werden, wenn dies für die Ausübung der Tätigkeiten nötig ist. Nachstehend sind die für den Selbstschutz nötigen grundsätzlichen Verhaltensregeln aufgeführt, welche unabhängig von der Tätigkeit beachtet werden müssen."
add("1.1","Gleisbereich betreten","Wann darf der Gleisbereich § betreten werden?","Nur wenn dies für die Ausübung der Tätigkeiten nötig ist.",["Jederzeit, sofern Warnkleidung getragen wird.","Nur nachts.","Nur mit Zustimmung des FDL."],F)
add("1.1","erhöhte Aufmerksamkeit","Was verlangt der Eisenbahnbetrieb § wegen seiner besonderen Gefahren von allen Mitarbeitenden?","Eine erhöhte Aufmerksamkeit.",["Eine zusätzliche Ausbildung.","Eine ärztliche Untersuchung pro Jahr.","Dauernde Funkbereitschaft."],F)
add("1.1","Verhaltensregeln Geltung","Für wen und wann gelten die grundsätzlichen Verhaltensregeln zum Selbstschutz §?","Unabhängig von der Tätigkeit für alle Mitarbeitenden.",["Nur für das Rangierpersonal.","Nur bei Arbeiten im Gleisbereich.","Nur bei Dunkelheit."],F)
F="Um Verletzungen zu verhindern, gilt für alle Mitarbeitenden die Grundregel: Gefahren erkennen; Gefahren vermeiden; Gefahren vermindern."
addm("1.2","Grundregel","Welche Grundregel gilt § für alle Mitarbeitenden, um Verletzungen zu verhindern (Mehrfachauswahl).",["Gefahren erkennen","Gefahren vermeiden","Gefahren vermindern"],["Gefahren dokumentieren","Gefahren delegieren"],F)
F="Vor Beginn jeder Tätigkeit haben die Mitarbeitenden die Gefahren einzuschätzen. Folgen dieser Gefahren sind insbesondere: überfahren werden (z.B. durch Rangierbewegungen, Zugfahrten oder ungesicherte Fahrzeuge); anstossen (z.B. durch Rangierbewegungen, ungesicherte Fahrzeuge oder Einragungen ins Lichtraumprofil); getroffen werden (z.B. durch herunterfallendes Ladegut, beim Ablad von Material); stürzen, stolpern, fallen (z.B. beim Auf- und Absteigen von Fahrzeugen, beim Gehen im Gleisfeld, durch Unordnung, bei Arbeiten in der Höhe); verbrennen (z.B. durch elektrischen Strom beim Besteigen von Fahrzeugen, Hantieren mit der Zugsammelschiene, Arbeiten in der Nähe von Fahrleitungen); verätzen, vergiften (z.B. durch Freisetzung von Gefahrgut, im Umgang mit Gefahrstoffen)."
add("1.2.1","Gefahren einschätzen","Wann haben die Mitarbeitenden die Gefahren § einzuschätzen?","Vor Beginn jeder Tätigkeit.",["Nur bei Arbeiten im Gleisbereich.","Nur bei Störungen.","Nach Abschluss jeder Tätigkeit."],F)
addm("1.2.1","Folgen von Gefahren","Welche Folgen von Gefahren nennt das Reglement § insbesondere (Mehrfachauswahl).",["Überfahren werden","Anstossen","Getroffen werden","Stürzen, stolpern, fallen","Verbrennen","Verätzen, vergiften"],["Ertrinken","Erfrieren"],F)
add("1.2.1","Folge Ladegut","Welche Folge von Gefahren droht § z.B. durch herunterfallendes Ladegut?","Getroffen werden.",["Überfahren werden.","Verbrennen.","Verätzen."],F)
add("1.2.1","Folge Lichtraumprofil","Welche Folge von Gefahren droht § z.B. durch Einragungen ins Lichtraumprofil?","Anstossen.",["Getroffen werden.","Stürzen.","Verbrennen."],F)
add("1.2.1","Folge Gefahrgut","Welche Folge von Gefahren droht § z.B. durch die Freisetzung von Gefahrgut?","Verätzen und vergiften.",["Anstossen.","Überfahren werden.","Stürzen, stolpern, fallen."],F)
F="Die Mitarbeitenden vermeiden mögliche Gefahren, indem sie insbesondere: Warnhinweise beachten; Schutzeinrichtungen benützen; sichere Wege (inklusive Unterführungen) ausserhalb des Gleisbereichs benutzen; Fahrleitungen ausschalten, erden und gegen unbeabsichtigtes Einschalten sichern lassen; Arbeiten möglichst ausserhalb des Gleisbereichs ausführen; sichere Standorte wählen; nur auf Fahrzeuge steigen oder von solchen absteigen, die stillstehen oder sich höchstens mit Schrittgeschwindigkeit bewegen; auf vorbeifahrende Züge und Rangierbewegungen achten; gefährliche Situationen melden; unsichere Zustände umgehend beheben oder kennzeichnen."
addm("1.2.2","Vermeidung Teil 1","Wie vermeiden die Mitarbeitenden mögliche Gefahren § insbesondere (Mehrfachauswahl).",["Sie beachten Warnhinweise","Sie benützen Schutzeinrichtungen","Sie führen Arbeiten möglichst ausserhalb des Gleisbereichs aus","Sie wählen sichere Standorte"],["Sie führen Arbeiten möglichst im Gleisbereich aus","Sie beachten Warnhinweise nur bei Dunkelheit"],F)
addm("1.2.2","Vermeidung Teil 2","Wie vermeiden die Mitarbeitenden mögliche Gefahren § ausserdem (Mehrfachauswahl).",["Sie achten auf vorbeifahrende Züge und Rangierbewegungen","Sie melden gefährliche Situationen","Sie beheben unsichere Zustände umgehend oder kennzeichnen sie"],["Sie melden gefährliche Situationen erst nach Schichtende","Sie ignorieren unsichere Zustände, die ihre eigene Tätigkeit nicht betreffen"],F)
add("1.2.2","Wege","Welche Wege benutzen die Mitarbeitenden §, um Gefahren zu vermeiden?","Sichere Wege (inklusive Unterführungen) ausserhalb des Gleisbereichs.",["Den kürzesten Weg durch den Gleisbereich.","Nur Wege entlang der Gleise.","Wege über stillstehende Fahrzeuge."],F)
add("1.2.2","Fahrleitungen","Was ist § mit Fahrleitungen zu tun, um Gefahren zu vermeiden?","Sie sind auszuschalten, zu erden und gegen unbeabsichtigtes Einschalten sichern zu lassen.",["Sie sind nur auszuschalten.","Sie sind nur zu erden.","Sie sind nur zu kennzeichnen."],F)
add("1.2.2","Auf- und Absteigen","Auf bzw. von welche Fahrzeuge darf § nur gestiegen werden?","Auf Fahrzeuge, die stillstehen oder sich höchstens mit Schrittgeschwindigkeit bewegen.",["Auf Fahrzeuge, die sich höchstens mit 10 km/h bewegen.","Auf Fahrzeuge, die sich höchstens mit 15 km/h bewegen.","Nur auf Fahrzeuge, die mit Hemmschuhen gesichert sind."],F)
F="Gefahren, die nicht vermieden werden können, vermindern die Mitarbeitenden insbesondere durch folgende Massnahmen: im Gleisbereich die Warnkleidung tragen, welche den gültigen Normen entsprechen muss. Rote Warnkleidungen sind jedoch verboten; persönliche Schutzausrüstungen gemäss den Bestimmungen des EBU tragen; Beleuchtung einschalten; Aufstiegshilfen benützen; Sicherheitseinrichtungen benützen; gefährdete Personen warnen."
addm("1.2.3","Verminderung","Durch welche Massnahmen vermindern die Mitarbeitenden Gefahren, die nicht vermieden werden können, § insbesondere (Mehrfachauswahl).",["Sie tragen im Gleisbereich Warnkleidung","Sie tragen persönliche Schutzausrüstungen gemäss den Bestimmungen des EBU","Sie schalten die Beleuchtung ein","Sie benützen Aufstiegshilfen","Sie benützen Sicherheitseinrichtungen","Sie warnen gefährdete Personen"],["Sie tragen rote Warnkleidung","Sie schalten die Beleuchtung aus"],F)
addm("1.2.3","Warnkleidung","Welche Aussagen zur Warnkleidung im Gleisbereich sind § richtig (Mehrfachauswahl).",["Sie muss den gültigen Normen entsprechen","Rote Warnkleidungen sind verboten"],["Gelbe Warnkleidungen sind verboten","Sie ist nur bei Dunkelheit zu tragen"],F)
add("1.2.3","Schutzausrüstung","Nach wessen Bestimmungen sind persönliche Schutzausrüstungen § zu tragen?","Nach den Bestimmungen des EBU.",["Nach den Bestimmungen der ISB.","Nach den Bestimmungen des BAV.","Nach den Bestimmungen des FDL."],F)
F="Vor dem Betreten oder Befahren (z.B. mit Stapler oder Gepäckfahrzeug) des Gleisbereichs haben die Mitarbeitenden wie folgt vorzugehen: einen Sicherheitshalt, mindestens 1,5 Meter vor der nächstgelegenen Schiene, einlegen; den Fluchtraum bestimmen; beachten, ob akustische oder optische Einrichtungen das Überqueren verbieten; mit Blick in beide Richtungen prüfen, ob sich keine Fahrzeuge nähern. Stillstehende Fahrzeuge müssen dabei mindestens 5 Meter von den Mitarbeitenden entfernt sein. Ausserdem haben die Mitarbeitenden innerhalb des Gleisbereichs insbesondere Folgendes zu beachten: sich in Vorwärtsrichtung bewegen; auf sichere Trittflächen achten; nicht auf Schienenköpfe und Weichenzungen treten; wenn immer möglich einen Abstand von mindestens 1,5 Meter von der nächstgelegenen Schiene einhalten; den Gleisbereich möglichst rasch verlassen."
addm("2.1","Vorgehen vor dem Betreten","Wie haben die Mitarbeitenden vor dem Betreten oder Befahren des Gleisbereichs § vorzugehen (Mehrfachauswahl).",["Sie legen einen Sicherheitshalt vor der nächstgelegenen Schiene ein","Sie bestimmen den Fluchtraum","Sie beachten, ob akustische oder optische Einrichtungen das Überqueren verbieten","Sie prüfen mit Blick in beide Richtungen, ob sich keine Fahrzeuge nähern"],["Sie holen die Zustimmung des FDL ein","Sie legen den Sicherheitshalt direkt an der Schiene ein"],F)
add("2.1","Sicherheitshalt Abstand","Wie weit vor der nächstgelegenen Schiene ist der Sicherheitshalt § mindestens einzulegen?","1,5 Meter.",["1 Meter.","2 Meter.","3 Meter."],F)
add("2.1","stillstehende Fahrzeuge Abstand","Wie weit müssen stillstehende Fahrzeuge bei der Prüfung vor dem Betreten des Gleisbereichs § mindestens von den Mitarbeitenden entfernt sein?","Mindestens 5 Meter.",["Mindestens 2 Meter.","Mindestens 3 Meter.","Mindestens 10 Meter."],F)
addm("2.1","Verhalten im Gleisbereich","Was haben die Mitarbeitenden innerhalb des Gleisbereichs § insbesondere zu beachten (Mehrfachauswahl).",["Sich in Vorwärtsrichtung bewegen","Auf sichere Trittflächen achten","Nicht auf Schienenköpfe und Weichenzungen treten","Wenn immer möglich einen Abstand von mindestens 1,5 Meter von der nächstgelegenen Schiene einhalten","Den Gleisbereich möglichst rasch verlassen"],["Sich rückwärts bewegen, um Fahrzeuge zu beobachten","Auf den Schienenköpfen gehen"],F)
add("2.1","Abstand im Gleisbereich","Welchen Abstand von der nächstgelegenen Schiene haben die Mitarbeitenden innerhalb des Gleisbereichs § wenn immer möglich einzuhalten?","Mindestens 1,5 Meter.",["Mindestens 0,5 Meter.","Mindestens 1 Meter.","Mindestens 3 Meter."],F)
F="Beim Aufenthalt und Arbeiten zwischen Gleisen oder zwischen einem Gleis und einem festen Hindernis muss ein Sicherheits-Zwischenraum vorhanden sein. Andernfalls ist nach den Bestimmungen «Fehlender Sicherheits-Zwischenraum» vorzugehen. Bei Arbeitsstellen ist nach den Bestimmungen über «Arbeiten im Gleisbereich» vorzugehen."
add("2.1.1","Sicherheits-Zwischenraum","Was muss § beim Aufenthalt und Arbeiten zwischen Gleisen vorhanden sein?","Ein Sicherheits-Zwischenraum.",["Eine Absperrung durch Warnsignale.","Ein Fluchtraum von mindestens 5 Metern.","Eine Begleitperson des FDL."],F)
add("2.1.1","Fehlender Zwischenraum Bestimmungen","Nach welchen Bestimmungen ist § vorzugehen, wenn kein Sicherheits-Zwischenraum vorhanden ist?","Nach den Bestimmungen «Fehlender Sicherheits-Zwischenraum».",["Nach den Bestimmungen «Arbeiten im Gleisbereich».","Nach den Bestimmungen «Gefahren des elektrischen Stroms».","Nach den Bestimmungen «Störungen an Sicherheitseinrichtungen»."],F)
add("2.1.1","Arbeitsstellen Bestimmungen","Nach welchen Bestimmungen ist § bei Arbeitsstellen vorzugehen?","Nach den Bestimmungen über «Arbeiten im Gleisbereich».",["Nach den Bestimmungen «Fehlender Sicherheits-Zwischenraum».","Nach den Bestimmungen «Gefahren des elektrischen Stroms».","Nach den Vorschriften über Rangierbewegungen."],F)
F="Ist kein Sicherheits-Zwischenraum vorhanden oder kann das betreffende Personal in der konkreten Situation nicht zweifelsfrei beurteilen, ob zwischen Gleise getreten werden darf, ist beim FDL die Sicherung der an den Gleiszwischenraum angrenzenden freien Gleise quittungspflichtig zu verlangen. Der FDL sichert und bestätigt die Sicherungsmassnahmen quittungspflichtig. Ist der Aufenthalt bzw. die Arbeit zwischen den Gleisen abgeschlossen, ist der FDL quittungspflichtig zu verständigen, damit der FDL die Sicherungsmassnahme wieder aufheben kann. Bei Arbeitsstellen ist nach den Bestimmungen über «Arbeiten im Gleisbereich» vorzugehen."
add("2.1.2","Wann Sicherung verlangen","Wann ist beim FDL die Sicherung der angrenzenden freien Gleise § zu verlangen?","Wenn kein Sicherheits-Zwischenraum vorhanden ist oder nicht zweifelsfrei beurteilt werden kann, ob zwischen Gleise getreten werden darf.",["Bei jedem Betreten des Gleisbereichs.","Nur bei Dunkelheit.","Nur wenn Fahrzeuge auf dem Nachbargleis stehen."],F)
addm("2.1.2","Ablauf Sicherung","Wie läuft das Vorgehen bei fehlendem Sicherheits-Zwischenraum § ab (Mehrfachauswahl).",["Das Personal verlangt die Sicherung der angrenzenden freien Gleise quittungspflichtig beim FDL","Der FDL sichert und bestätigt die Sicherungsmassnahmen quittungspflichtig","Nach Abschluss der Arbeit wird der FDL quittungspflichtig verständigt"],["Das Personal sichert die angrenzenden Gleise selbst mit Hemmschuhen","Der FDL hebt die Sicherung ohne Verständigung nach einer festen Zeit auf"],F)
F="Müssen sich Mitarbeitende für Arbeiten auf, zwischen oder unter Fahrzeuge begeben, stellen sie sicher, dass sich die Fahrzeuge nicht ungewollt bewegen können. Ausserdem ist das beteiligte Personal insbesondere in folgenden Fällen zu verständigen: vor dem Kuppeln oder Entkuppeln von Fahrzeugen; auf dem Ausgangsbahnhof, wenn die Zugsuntersuchung bereits abgeschlossen ist; auf einem Unterwegsbahnhof bei Zügen; bei Rangierbewegungen, wenn bereits ein Fahrbefehl erteilt wurde; vor dem Beginn von Reparatur- und Unterhaltsarbeiten sowie der Störungsbehebung. Müssen Mitarbeitende auf Fahrzeuge steigen (z.B. für Be- und Entlad, Kontrolltätigkeiten, Störungsbehebung), haben sie zusätzlich Folgendes zu beachten: die Bestimmungen über die «Gefahren des elektrischen Stroms»; die dafür vorgesehenen festen Einrichtungen oder mobilen Aufstiegshilfen benutzen; bei Tätigkeiten auf Fahrzeugdächer Absturzsicherungen verwenden. Der Abschluss der Arbeiten ist dem beteiligten Personal zu melden."
add("2.3.1","Fahrzeuge nicht bewegen","Was stellen die Mitarbeitenden § sicher, wenn sie sich für Arbeiten auf, zwischen oder unter Fahrzeuge begeben müssen?","Dass sich die Fahrzeuge nicht ungewollt bewegen können.",["Dass die Fahrzeuge mit Strom versorgt sind.","Dass die Fahrzeuge beleuchtet sind.","Dass die Fahrzeuge gebremst fahren."],F)
addm("2.3.1","Verständigung beteiligtes Personal","In welchen Fällen ist das beteiligte Personal § insbesondere zu verständigen (Mehrfachauswahl).",["Vor dem Kuppeln oder Entkuppeln von Fahrzeugen","Auf dem Ausgangsbahnhof, wenn die Zuguntersuchung bereits abgeschlossen ist","Auf einem Unterwegsbahnhof bei Zügen","Bei Rangierbewegungen, wenn bereits ein Fahrbefehl erteilt wurde","Vor dem Beginn von Reparatur- und Unterhaltsarbeiten sowie der Störungsbehebung"],["Bei jeder Zugdurchfahrt","Bei Schichtbeginn"],F)
addm("2.3.1","Auf Fahrzeuge steigen","Was haben Mitarbeitende § zusätzlich zu beachten, wenn sie auf Fahrzeuge steigen müssen (Mehrfachauswahl).",["Die Bestimmungen über die «Gefahren des elektrischen Stroms»","Sie benutzen die dafür vorgesehenen festen Einrichtungen oder mobilen Aufstiegshilfen","Bei Tätigkeiten auf Fahrzeugdächern verwenden sie Absturzsicherungen"],["Sie steigen über die Puffer auf","Sie verwenden Absturzsicherungen nur bei Dunkelheit"],F)
add("2.3.1","Abschluss der Arbeiten","Wem ist der Abschluss der Arbeiten an Fahrzeugen § zu melden?","Dem beteiligten Personal.",["Nur dem FDL.","Nur dem ZVB.","Niemandem, wenn nichts Besonderes vorgefallen ist."],F)
F="Müssen Mitarbeitende auf Fahrzeugen mitfahren, haben sie Folgendes zu beachten: nur mitfahren, wenn es für die Arbeitsausübung notwendig ist; bei der Mitfahrt im bedienten Führerstand darf der LF bei der Arbeit weder behindert noch abgelenkt werden; sicheren Standort wählen (z.B. Trittbrett oder Plattform, vorhandene Haltevorrichtungen); Gefahren des Fahrwegs berücksichtigen (z.B. Rampen, Toreinfahrten, Infrastrukturanlagen mit kritischem Sicherheitsabstand)."
addm("2.3.2","Mitfahrt","Was haben Mitarbeitende § bei der Mitfahrt auf Fahrzeugen zu beachten (Mehrfachauswahl).",["Nur mitfahren, wenn es für die Arbeitsausübung notwendig ist","Der LF darf bei der Mitfahrt im bedienten Führerstand weder behindert noch abgelenkt werden","Einen sicheren Standort wählen","Die Gefahren des Fahrwegs berücksichtigen"],["Einen beliebigen Standort wählen","Immer mitfahren, wenn Platz vorhanden ist"],F)
addm("2.3.2","Gefahren des Fahrwegs","Welche Beispiele für Gefahren des Fahrwegs nennt das Reglement § (Mehrfachauswahl).",["Rampen","Toreinfahrten","Infrastrukturanlagen mit kritischem Sicherheitsabstand"],["Bahnhofuhren","Signaltafeln am Perron"],F)
add("2.3.2","sicherer Standort","Was ist § z.B. ein sicherer Standort bei der Mitfahrt?","Ein Trittbrett oder eine Plattform mit vorhandenen Haltevorrichtungen.",["Die Kupplung zwischen den Fahrzeugen.","Der Puffer.","Das Fahrzeugdach."],F)
F="Die elektrischen Anlagen (z.B. Fahrleitung, Zugsammelschiene) sind immer als unter Spannung zu betrachten, bis man sich vom Gegenteil überzeugt hat. Zur Vermeidung von Risiken und Gefahren muss vor der Arbeitsaufnahme oder dem Besteigen von Fahrzeugdächern, Kesselwagen usw. oder von Wagenladungen sichergestellt sein, dass die Fahrleitung ausgeschaltet, geerdet und gegen unbeabsichtigtes Einschalten gesichert ist. Je nach elektrischer Anlage oder wenn das Erden nicht möglich ist, muss eine SPEA beigezogen werden. IPEA dürfen ausnahmsweise erhöhte Fahrzeugbereiche und Wagenladungen auch unter eingeschalteten Fahrleitungen besteigen."
add("2.4.1","Anlagen unter Spannung","Wie sind elektrische Anlagen wie Fahrleitung oder Zugsammelschiene § zu betrachten?","Immer als unter Spannung, bis man sich vom Gegenteil überzeugt hat.",["Als spannungsfrei, bis das Gegenteil bekannt ist.","Als spannungsfrei, wenn der Stromabnehmer gesenkt ist.","Als spannungsfrei ausserhalb der Betriebszeiten."],F)
addm("2.4.1","Sicherstellen Fahrleitung","Was muss § vor der Arbeitsaufnahme oder dem Besteigen von Fahrzeugdächern sichergestellt sein (Mehrfachauswahl).",["Die Fahrleitung ist ausgeschaltet","Die Fahrleitung ist geerdet","Die Fahrleitung ist gegen unbeabsichtigtes Einschalten gesichert"],["Die Fahrleitung ist abgesenkt","Die Fahrleitungsmasten sind gekennzeichnet"],F)
add("2.4.1","SPEA beiziehen","Wann muss § eine SPEA beigezogen werden?","Je nach elektrischer Anlage oder wenn das Erden nicht möglich ist.",["Bei jeder Arbeit im Gleisbereich.","Nur bei Nacht.","Nur bei Rangierbewegungen."],F)
add("2.4.1","IPEA Ausnahme","Wer darf § ausnahmsweise erhöhte Fahrzeugbereiche und Wagenladungen auch unter eingeschalteten Fahrleitungen besteigen?","IPEA.",["Jeder LF.","Der ZVB.","Der FDL."],F)
F="Bei elektrischen Anlagen kann Lebensgefahr bestehen, insbesondere: durch direkten Kontakt; durch Annäherung; durch Trennen bzw. Verbinden von gewissen eingeschalteten elektrischen Verbindungen (z.B. Zugsammelschienen, Hörnerschalter unter Last); bei Unterbrechung des Stromkreises von über den Stromabnehmer oder die Zugsammelschiene gespeisten Fahrzeugen, insbesondere wenn diese auf einer isolierenden Schicht von Sand, Rost, Abfällen, Eis, Schnee usw. stehen und Kontakt zur Fahrleitung haben. Bei Entgleisungen muss der Stromabnehmer sofort gesenkt und die Zugsammelschiene ausgeschaltet werden. Nötigenfalls sind solche Fahrzeuge mit einem Sprung zu verlassen. Bei der Ausführung von bestimmten Arbeiten besteht die Gefahr, dass die Sicherheitsabstände zur Fahrleitung oder anderen spannungsführenden Teilen nicht eingehalten werden, insbesondere: bei Verlade- und Entladearbeiten; beim Einsatz von Bau- und Hebegeräten; bei Reparaturarbeiten in der Höhe; zum Wechseln bestimmter Signallampen; beim Reinigen von Tafeln, Anzeigen, Beleuchtung usw.; wenn Teile der Fahrleitung beschädigt sind bzw. herunterhängen; beim Einsatz von Hochdruckwassergeräten; bei Untersuchungsarbeiten (z.B. Messungen)."
addm("2.4.2","Lebensgefahr elektrisch","Wodurch kann bei elektrischen Anlagen § insbesondere Lebensgefahr bestehen (Mehrfachauswahl).",["Durch direkten Kontakt","Durch Annäherung","Durch Trennen bzw. Verbinden von gewissen eingeschalteten elektrischen Verbindungen","Bei Unterbrechung des Stromkreises von über den Stromabnehmer oder die Zugsammelschiene gespeisten Fahrzeugen"],["Durch Sichtkontakt","Durch Lärm"],F)
addm("2.4.2","Entgleisung","Was muss § bei Entgleisungen sofort geschehen (Mehrfachauswahl).",["Der Stromabnehmer muss gesenkt werden","Die Zugsammelschiene muss ausgeschaltet werden"],["Der Stromabnehmer muss gehoben bleiben","Die Zugsammelschiene muss eingeschaltet bleiben"],F)
add("2.4.2","Fahrzeug verlassen","Wie sind Fahrzeuge § nötigenfalls zu verlassen, wenn sie bei einer Entgleisung Kontakt zur Fahrleitung haben?","Mit einem Sprung.",["Über die Aufstiegshilfen.","Erst nach dem Ausschalten durch den FDL.","Schritt für Schritt über die Trittbretter."],F)
addm("2.4.2","Arbeiten Sicherheitsabstand 1","Bei welchen Arbeiten besteht § die Gefahr, dass die Sicherheitsabstände zur Fahrleitung nicht eingehalten werden (Mehrfachauswahl).",["Bei Verlade- und Entladearbeiten","Beim Einsatz von Bau- und Hebegeräten","Bei Reparaturarbeiten in der Höhe","Zum Wechseln bestimmter Signallampen","Beim Reinigen von Tafeln, Anzeigen, Beleuchtung usw."],["Beim Fahren im bedienten Führerstand","Beim Kuppeln von Fahrzeugen","Bei Büroarbeiten"],F)
addm("2.4.2","Arbeiten Sicherheitsabstand 2","Welche weiteren Situationen führen § zur Gefahr, dass Sicherheitsabstände zur Fahrleitung nicht eingehalten werden (Mehrfachauswahl).",["Beschädigte bzw. herunterhängende Teile der Fahrleitung","Der Einsatz von Hochdruckwassergeräten","Untersuchungsarbeiten (z.B. Messungen)"],["Das Bedienen von Weichen von Hand","Das Anziehen der Handbremse"],F)
F="Strahlrohre und Wasserwerfer dürfen nicht eingesetzt werden, wenn stromführende Anlagen im möglichen Wirkungsbereich liegen. Für den Einsatz von Sprühdüsen und ähnlichen Geräten mit nur kurzem Wirkungsbereich können die EBU Betriebsvorschriften erlassen."
add("2.4.3","Strahlrohre","Wann dürfen Strahlrohre und Wasserwerfer § nicht eingesetzt werden?","Wenn stromführende Anlagen im möglichen Wirkungsbereich liegen.",["Wenn die Fahrleitung ausgeschaltet ist.","Bei Nacht.","Wenn Fahrzeuge im Gleis stehen."],F)
add("2.4.3","Sprühdüsen","Für welche Geräte können die EBU § Betriebsvorschriften erlassen?","Für Sprühdüsen und ähnliche Geräte mit nur kurzem Wirkungsbereich.",["Für Strahlrohre.","Für Wasserwerfer.","Für Hochdruckreiniger mit grosser Reichweite."],F)
run(seed=1605,new_reg=('r8','R 300.8','R 300.8 ARBEITSSICHERHEIT'))
